// Throwaway verification of preflight.mjs's SQL classifier + schema parser.
// Nothing here touches the database.
import { readFileSync } from "node:fs";
import { execFileSync } from "node:child_process";

const ROOT = "C:/Users/edmem/kodely-prod";
const src = readFileSync(`${ROOT}/scripts/preflight.mjs`, "utf8");

function slice(name) {
  const start = src.indexOf(`function ${name}(`);
  if (start < 0) throw new Error(`no ${name}`);
  let i = src.indexOf("{", start), depth = 0;
  for (let j = i; j < src.length; j++) {
    if (src[j] === "{") depth++;
    else if (src[j] === "}") { depth--; if (depth === 0) return src.slice(start, j + 1); }
  }
  throw new Error("unbalanced");
}

const SCALARS_SRC = src.slice(src.indexOf("const SCALARS"), src.indexOf("]);", src.indexOf("const SCALARS")) + 3);
const mod = new Function(`${SCALARS_SRC}\n${slice("classifySql")}\n${slice("parsePrismaSchema")}\nreturn {classifySql, parsePrismaSchema};`)();

// 1. A REAL prisma-generated script for the worst case: the database has nothing.
const sql = execFileSync(
  process.execPath,
  [`${ROOT}/node_modules/prisma/build/index.js`, "migrate", "diff",
   "--from-empty", "--to-schema-datamodel", "prisma/schema.prisma", "--script"],
  { cwd: ROOT, encoding: "utf8", maxBuffer: 1 << 26 },
);
const empty = mod.classifySql(sql);
const tables = empty.missing.filter((s) => s.startsWith("table ")).map((s) => s.slice(6));
console.log("=== from-empty (DB has nothing) ===");
console.log("missing objects:", empty.missing.length, "| extra:", empty.extra.length);
console.log("tables detected:", tables.length, tables.sort().join(", "));
const RELEASE = ["Event","LoginAttempt","EmailLog","AdminAuditLog","FeatureFlag","ModerationFinding","SupportNote","FormSubmission"];
console.log("all 8 release models detected:", RELEASE.every((t) => tables.includes(t)));
console.log("sample columns:", empty.missing.filter((s) => s.startsWith("column ")).slice(0, 3));

// 2. Hand-made mixed script: one missing table, one missing column, one extra column.
const mixed = mod.classifySql(`
-- some comment
CREATE TABLE "Event" ("id" TEXT NOT NULL);
ALTER TABLE "User" ADD COLUMN "spendCapCredits" INTEGER;
ALTER TABLE "Build" DROP COLUMN "legacyField";
DROP TABLE "OldThing";
CREATE UNIQUE INDEX "EmailLog_kind_dedupeKey_key" ON "EmailLog"("kind", "dedupeKey");
ALTER TABLE "Project" ALTER COLUMN "name" SET NOT NULL;
`);
console.log("\n=== mixed script ===");
console.log("missing:", mixed.missing);
console.log("extra:", mixed.extra);

// 3. Schema parser: model/column extraction, relation fields excluded.
const models = mod.parsePrismaSchema(readFileSync(`${ROOT}/prisma/schema.prisma`, "utf8"));
console.log("\n=== parsePrismaSchema ===");
console.log("models:", models.length);
const user = models.find((m) => m.table === "User");
console.log("User columns:", user.cols.join(", "));
console.log("User excludes relation fields (sessions/projects/ledger/events/supportNotes):",
  !["sessions", "projects", "ledger", "events", "supportNotes"].some((f) => user.cols.includes(f)));
console.log("Build.repairAttempts present:", models.find((m) => m.table === "Build").cols.includes("repairAttempts"));

